  // Data-only replies share registration logic; executable commands stay explicit.
  function registerSpec(spec) {
    if (spec.patterns) {
      spec.match = spec.patterns.map(function (pattern) { return new RegExp(pattern, "i"); });
      delete spec.patterns;
    }
    if (typeof spec.reply === "string") {
      var message = spec.reply;
      delete spec.reply;
      spec.run = function (text) { return { ok: true, message: message }; };
    }
    C.register(spec);
  }
  specs.forEach(registerSpec);
